def shortest_path(graph, source, target):
    # Initialize the distance and path with a large number
    # and also store the path that leads to these distances with a list of nodes.
    # We use a list of tuples to keep the path. Each tuple is (distance, path).
    # The path is a list of nodes, starting from the source.
    distances = {(source: tuple([source])): 0}
    path_found = {(source: tuple([source])): []}

    # A set to keep track of nodes we have already visited
    visited = set()

    # Priority queue to keep track of the next node to visit
    # The queue is a list of tuples where each tuple is (distance, node)
    queue = [(0, source)]

    while queue:
        # Pop the node with the smallest distance
        current_distance, current_node = queue.pop(0)

        # If we have already visited this node, skip it
        if current_node in visited:
            continue
        visited.add(current_node)

        # If we have reached the target, we can stop
        if current_node == target:
            return (current_distance, path_found[current_node])

        # Explore the neighbors
        for neighbor, weight in graph.get(current_node, []):
            new_distance = current_distance + weight
            if neighbor not in visited:
                # If the new path is shorter, update the distance and path
                if new_distance < distances.get((neighbor: tuple([neighbor])), float('inf')):
                    distances[(neighbor: tuple([neighbor]))] = new_distance
                    path_found[(neighbor: tuple([neighbor]))] = path_found[current_node] + [neighbor]
                    queue.append((new_distance, neighbor))

    # If we exit the loop without finding the target, the target is unreachable
    return (float('inf'), None)

